		/*selectMasterWmDlDlvryCenter*/
		                SELECT 
                REPLACE(TEXT5,'param',#{st_delivery_no}) TEXT5_ADDR
                 FROM ICOMCOD1 
                 WHERE TYPE = 'C019'
                      AND CODE = #{st_delivery_company}

mapper.update:

			/*updateMasterWmDlDlvryCenter*/
			UPDATE WMSIVDT
     			SET DELIVERY_COMPANY = #{st_delivery_company}
                    , DELIVERY_NO = #{st_delivery_no}
                    , PARCEL_ADD_DATE = SYSDATE
                    , PARCEL_ADD_USER_ID = #{st_user_id}
           WHERE WAREHOUSE_CODE =#{st_warehouse_code}    	
               AND INV_NO = #{IK_NO}
               AND BUYER = #{BUYER}


UPDATE WMSSTCK SET TOT_QTY = TOT_QTY - (#{INV_QTY}), 
					  ALLOC_QTY = ALLOC_QTY - (#{INV_QTY}), 
					  CHANGE_DATE = TO_CHAR(SYSDATE,'YYYYMMDD'), 
					  CHANGE_USER =  #{st_user_id}
WHERE WAREHOUSE_CODE = #{st_warehouse_code}    
  AND STDCATLG_ID = #{CMS_CATLG_ID} 
  AND AGENT    = DECODE(#{PROCESS_TYPE},'1','KRKORE0001',(SELECT WAREHOUSE_CODE FROM ICOMPODT WHERE BUYER = #{BUYER} AND PO_NO = #{PO_NO} AND PO_SEQ = #{PO_SEQ}))


/*updateMasterWmDlWmsWarhsngProcPodt*/
UPDATE ICOMPODT
SET
	GR_QTY = NVL(GR_QTY,0) + #{GR_QTY}
WHERE
		BUYER 	= #{BUYER}
	AND SELLER  = 'KRKORE0001'
	AND PO_NO   = #{PO_NO}
	AND PO_SEQ  = #{PO_SEQ}
	AND STATUS != 'D'


/*updateMasterWmDlWmsWarhsngProcWmsIvdt*/
UPDATE WMSIVDT A 
SET
	  A.BUYER_GR_QTY = NVL(BUYER_GR_QTY,0) + ${GR_QTY}
	, CHANGE_DATE = TO_CHAR(SYSDATE,'YYYYMMDD')
	, CHANGE_TIME = TO_CHAR(SYSDATE,'HH24MISS')
WHERE 
		A.BUYER  = #{BUYER}
	AND A.SELLER   = 'KRKORE0001'
	AND A.INV_NO   = #{INV_NO}
	AND A.INV_SEQ  = #{INV_SEQ}
	AND A.STATUS  != 'D'
